import lab

def preview_line(board, side, moves):
    from copy import deepcopy
    work=deepcopy(board);turn=side;captured=[]
    for i,move in enumerate(moves):
        if tuple(move) not in lab.legal_moves(work,turn):
            return {'status':'illegal','index':i,'board':deepcopy(board),'side':side,'captured':[]}
        captured.append(lab.make_move(work,move));turn=lab.opponent(turn)
    return {'status':'ok','index':None,'board':work,'side':turn,'captured':captured}

import lab

def explain_score_change(before, after, weights):
    def parts(b):
        material=position=0
        for y,row in enumerate(b):
            for x,p in enumerate(row):
                if p=='.': continue
                material+=weights[p.upper()]*(1 if p.isupper() else -1)
                position+=lab.pawn_bonus(p,x,y)
        return material,position
    bm,bp=parts(before);am,ap=parts(after);m,p=am-bm,ap-bp;t=m+p
    return {'material_delta':m,'position_delta':p,'total_delta':t,'favours':'red' if t>0 else 'black' if t<0 else 'neither'}

import lab

def compare_depths(options, side):
    if not options: return {'greedy':None,'robust':None,'scores':{},'changed':False}
    ordered=sorted(options,key=lambda o:o['id'])
    select=max if side=='red' else min
    greedy=select(ordered,key=lambda o:o['static'])['id']
    scores={o['id']:(min(o['replies']) if side=='red' else max(o['replies'])) if o['replies'] else (lab.MATE if side=='red' else -lab.MATE) for o in ordered}
    robust=select(ordered,key=lambda o:scores[o['id']])['id']
    return {'greedy':greedy,'robust':robust,'scores':scores,'changed':greedy!=robust}

import lab

def cutoff_certificate(side, alpha, beta, child_scores):
    best=None;visited=0
    for score in child_scores:
        best=score if best is None else (max(best,score) if side=='red' else min(best,score))
        visited+=1
        if side=='red': alpha=max(alpha,best)
        else: beta=min(beta,best)
        if alpha>=beta: break
    skipped=len(child_scores)-visited
    bound='none' if not child_scores else ('lower' if side=='red' else 'upper') if skipped else 'exact'
    return {'visited':visited,'skipped':skipped,'best':best,'alpha':alpha,'beta':beta,'bound':bound,'pruned':skipped>0}
